  function addKeeperPassage(pageIndex, anchor, passage) {
    const page = keepersReturnBook?.pages?.[pageIndex];
    if (!page || !page.text.includes(anchor)) return;
    const cleanPassage = passage.trim().replace(/\n  /g, "\n");
    page.text = page.text.replace(anchor, `${anchor}\n\n${cleanPassage}`);
  }

  function addKeeperPassageBefore(pageIndex, anchor, passage) {
    const page = keepersReturnBook?.pages?.[pageIndex];
    if (!page || !page.text.includes(anchor)) return;
    const cleanPassage = passage.trim().replace(/\n  /g, "\n");
    const anchoredText = page.text.includes(` ${anchor}`) ? ` ${anchor}` : anchor;
    page.text = page.text.replace(anchoredText, `\n\n${cleanPassage}\n\n${anchor}`);
  }

  function replaceKeeperPassageOccurrence(pageIndex, passage, occurrence, replacement) {
    const page = keepersReturnBook?.pages?.[pageIndex];
    if (!page) return;
    let startIndex = -1;
    let searchFrom = 0;
    for (let index = 0; index < occurrence; index += 1) {
      startIndex = page.text.indexOf(passage, searchFrom);
      if (startIndex < 0) return;
      searchFrom = startIndex + passage.length;
    }
    page.text = `${page.text.slice(0, startIndex)}${replacement.trim()}${page.text.slice(startIndex + passage.length)}`;
  }

